//! Benchmark data model shared with the frontend (TypeScript generated by
//! ts-rs). Raw measurements are always kept next to derived values: scores
//! are presentation aids, samples are the source of truth.

use serde::{Deserialize, Serialize};

use crate::errors::{AppError, ErrorKind};

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub enum BenchmarkKind {
    Cpu,
    Gpu,
    Disk,
    Network,
}

impl BenchmarkKind {
    /// Execution order of a full run: heavy local tests first (CPU, then GPU
    /// after a cooldown), storage next, and the internet last so network
    /// traffic never overlaps a local measurement.
    pub const ORDER: [Self; 4] = [Self::Cpu, Self::Gpu, Self::Disk, Self::Network];

    pub const fn label(self) -> &'static str {
        match self {
            Self::Cpu => "CPU",
            Self::Gpu => "GPU",
            Self::Disk => "Disk",
            Self::Network => "Internet",
        }
    }

    /// Categories that stress local hardware and benefit from a cooldown
    /// before the next heavy category.
    pub const fn is_heavy(self) -> bool {
        matches!(self, Self::Cpu | Self::Gpu)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub enum BenchmarkProfile {
    Quick,
    #[default]
    Standard,
    Extended,
}

impl BenchmarkProfile {
    /// Measured iterations per subtest.
    pub const fn iterations(self) -> u32 {
        match self {
            Self::Quick => 5,
            Self::Standard => 7,
            Self::Extended => 10,
        }
    }

    /// Warmup before measurement, in milliseconds (never measured).
    pub const fn warmup_ms(self) -> u64 {
        match self {
            Self::Quick => 1_000,
            Self::Standard => 2_000,
            Self::Extended => 3_000,
        }
    }

    /// Cooldown between heavy categories. Quick runs never wait.
    pub const fn cooldown_secs(self) -> u32 {
        match self {
            Self::Quick => 0,
            Self::Standard => 10,
            Self::Extended => 30,
        }
    }

    /// Hard ceiling for a whole run; exceeding it fails the run cleanly
    /// instead of letting a stuck workload run forever.
    pub const fn timeout_secs(self) -> u64 {
        match self {
            Self::Quick => 15 * 60,
            Self::Standard => 30 * 60,
            Self::Extended => 90 * 60,
        }
    }
}

/// Lifecycle of a run. Transitions only move forward; the last three are
/// terminal.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub enum BenchmarkPhase {
    Idle,
    Preparing,
    WarmingUp,
    Running,
    CoolingDown,
    Finalizing,
    Completed,
    Cancelled,
    Failed,
}

impl BenchmarkPhase {
    pub const fn is_terminal(self) -> bool {
        matches!(self, Self::Completed | Self::Cancelled | Self::Failed)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub enum NetworkDataProfile {
    DataSaver,
    #[default]
    Standard,
    Maximum,
}

impl NetworkDataProfile {
    /// Upper bound of transferred data, in bytes (decimal MB). Providers are
    /// adaptive, so the UI presents this as "up to approximately".
    pub const fn max_bytes(self) -> u64 {
        match self {
            Self::DataSaver => 25_000_000,
            Self::Standard => 200_000_000,
            Self::Maximum => 1_000_000_000,
        }
    }
}

/// What the user asked to run. Everything here is untrusted and checked by
/// [`crate::benchmarks::validate_request`].
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub struct BenchmarkRequest {
    pub kinds: Vec<BenchmarkKind>,
    pub profile: BenchmarkProfile,
    /// `None` = one worker per logical processor.
    pub cpu_workers: Option<u32>,
    /// Adapter id from the capabilities list; `None` = high-performance default.
    pub gpu_adapter_id: Option<String>,
    /// Mount point from the capabilities list.
    pub disk_mount_point: Option<String>,
    pub disk_allow_write: bool,
    pub network_data_profile: NetworkDataProfile,
    /// Extended-profile sustained phase length; `None` = default.
    pub sustained_secs: Option<u32>,
    /// Pause between heavy categories (skippable while it runs).
    pub cooldown: bool,
    /// Run deterministic mock workloads instead of real ones (development
    /// and UI testing; refused unless simulation is enabled).
    pub simulate: bool,
}

/// One live measurement for charts while a test runs.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub struct LiveSample {
    /// Milliseconds since the run started.
    pub t_ms: u64,
    /// Stable series id, e.g. `cpu.throughput`.
    pub series: String,
    pub value: f64,
    pub unit: MetricUnit,
}

