#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub struct FailureInfo {
    pub kind: ErrorKind,
    pub message: String,
}

impl From<&AppError> for FailureInfo {
    fn from(e: &AppError) -> Self {
        Self {
            kind: e.kind(),
            message: e.to_string(),
        }
    }
}

/// Units are explicit so the UI never confuses MB/s with Mbps.
/// Throughput units are decimal (1 MB = 10^6 bytes, 1 Mbps = 10^6 bit/s).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub enum MetricUnit {
    /// Million operations per second.
    Mops,
    /// Million floating-point operations per second.
    Mflops,
    /// Billion floating-point operations per second.
    Gflops,
    /// Megabytes (10^6) per second.
    MegabytesPerSec,
    /// Gigabytes (10^9) per second.
    GigabytesPerSec,
    /// Megabits (10^6) per second.
    Mbps,
    Iops,
    Milliseconds,
    Microseconds,
    Percent,
    /// Dimensionless ratio, e.g. multi-core scaling or compression ratio.
    Ratio,
    Celsius,
    Megahertz,
    Bytes,
}

#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub struct Summary {
    pub n: u32,
    pub mean: f64,
    pub median: f64,
    pub min: f64,
    pub max: f64,
    /// Sample standard deviation (n − 1).
    pub std_dev: f64,
    /// Coefficient of variation in percent (std_dev / mean × 100).
    pub cv_percent: f64,
    pub p50: f64,
    pub p90: f64,
    pub p95: f64,
    pub p99: f64,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub struct Metric {
    /// Stable id used by scoring, comparison and history, e.g. `cpu.single.integer`.
    pub id: String,
    pub label: String,
    pub unit: MetricUnit,
    pub higher_is_better: bool,
    /// Headline value (the median for multi-sample metrics).
    pub value: f64,
    pub summary: Option<Summary>,
    /// Raw per-iteration measurements, in measurement order.
    pub samples: Vec<f64>,
    /// Indices into `samples` flagged as outliers (kept, not removed).
    pub outliers: Vec<u32>,
    /// Score contribution of this metric, if it is scored.
    pub score: Option<f64>,
    pub note: Option<String>,
}

