/// A point of a sustained-performance or sensor timeline.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub struct TimelinePoint {
    /// Milliseconds since the category started.
    pub t_ms: u64,
    pub series: String,
    pub value: f64,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub struct CategoryResult {
    pub kind: BenchmarkKind,
    pub status: CategoryStatus,
    pub metrics: Vec<Metric>,
    pub score: Option<f64>,
    pub confidence: Option<Confidence>,
    pub warnings: Vec<BenchmarkWarning>,
    pub details: Vec<Detail>,
    pub timeline: Vec<TimelinePoint>,
    pub duration_ms: u64,
    pub error: Option<FailureInfo>,
    /// Background load observed while this category ran.
    pub interference: Option<InterferenceReport>,
    pub thermal: Option<ThermalObservation>,
}

impl CategoryResult {
    pub fn empty(kind: BenchmarkKind, status: CategoryStatus) -> Self {
        Self {
            kind,
            status,
            metrics: Vec::new(),
            score: None,
            confidence: None,
            warnings: Vec::new(),
            details: Vec::new(),
            timeline: Vec::new(),
            duration_ms: 0,
            error: None,
            interference: None,
            thermal: None,
        }
    }

    pub fn metric(&self, id: &str) -> Option<&Metric> {
        self.metrics.iter().find(|m| m.id == id)
    }
}

