/// A stored benchmark run.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub struct BenchmarkRecord {
    pub schema_version: u32,
    pub method_version: String,
    pub score_version: u32,
    pub id: String,
    pub started_at_ms: u64,
    pub duration_ms: u64,
    pub app_version: String,
    pub profile: BenchmarkProfile,
    pub kinds: Vec<BenchmarkKind>,
    pub simulated: bool,
    pub environment_before: EnvironmentSnapshot,
    pub environment_after: Option<EnvironmentSnapshot>,
    pub fingerprint: HardwareFingerprint,
    pub categories: Vec<CategoryResult>,
    pub system_score: Option<SystemScore>,
    pub warnings: Vec<BenchmarkWarning>,
}

impl BenchmarkRecord {
    pub fn category(&self, kind: BenchmarkKind) -> Option<&CategoryResult> {
        self.categories.iter().find(|c| c.kind == kind)
    }
}

/// Lightweight view of a record for history lists and charts.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub struct BenchmarkSummary {
    pub id: String,
    pub started_at_ms: u64,
    pub duration_ms: u64,
    pub profile: BenchmarkProfile,
    pub method_version: String,
    pub score_version: u32,
    pub simulated: bool,
    pub fingerprint: HardwareFingerprint,
    pub system_score: Option<SystemScore>,
    pub categories: Vec<CategorySummary>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub struct CategorySummary {
    pub kind: BenchmarkKind,
    pub status: CategoryStatus,
    pub score: Option<f64>,
    pub confidence: Option<Confidence>,
    pub metrics: Vec<MetricValue>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub struct MetricValue {
    pub id: String,
    pub label: String,
    pub unit: MetricUnit,
    pub value: f64,
    pub cv_percent: Option<f64>,
}

impl From<&BenchmarkRecord> for BenchmarkSummary {
    fn from(r: &BenchmarkRecord) -> Self {
        Self {
            id: r.id.clone(),
            started_at_ms: r.started_at_ms,
            duration_ms: r.duration_ms,
            profile: r.profile,
            method_version: r.method_version.clone(),
            score_version: r.score_version,
            simulated: r.simulated,
            fingerprint: r.fingerprint.clone(),
            system_score: r.system_score.clone(),
            categories: r
                .categories
                .iter()
                .map(|c| CategorySummary {
                    kind: c.kind,
                    status: c.status,
                    score: c.score,
                    confidence: c.confidence,
                    metrics: c
                        .metrics
                        .iter()
                        .map(|m| MetricValue {
                            id: m.id.clone(),
                            label: m.label.clone(),
                            unit: m.unit,
                            value: m.value,
                            cv_percent: m.summary.as_ref().map(|s| s.cv_percent),
                        })
                        .collect(),
                })
                .collect(),
        }
    }
}

