/// Cap on bytes the disk benchmark may write in one run (SSD wear guard).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub enum DiskWriteLimit {
    Conservative,
    #[default]
    Standard,
    Extended,
}

impl DiskWriteLimit {
    pub const fn max_bytes(self) -> u64 {
        const GIB: u64 = 1024 * 1024 * 1024;
        match self {
            Self::Conservative => GIB,
            Self::Standard => 4 * GIB,
            Self::Extended => 16 * GIB,
        }
    }
}

