/// Persisted benchmark preferences (nested in [`crate::models::Settings`]).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase", default)]
pub struct BenchmarkSettings {
    pub profile: BenchmarkProfile,
    /// `None` = automatic (one worker per logical processor).
    pub cpu_workers: Option<u32>,
    pub gpu_adapter_id: Option<String>,
    pub disk_mount_point: Option<String>,
    pub disk_allow_write: bool,
    pub disk_write_limit: DiskWriteLimit,
    pub network_provider: NetworkProviderId,
    pub network_data_profile: NetworkDataProfile,
    /// The internet-test privacy notice was acknowledged.
    pub network_privacy_accepted: bool,
    /// Let the provider keep anonymized results (off by default).
    pub network_share_results: bool,
    pub save_history: bool,
    pub cooldown: bool,
    pub sustained_secs: u32,
    pub show_raw_measurements: bool,
    pub show_methodology: bool,
    pub debug_logging: bool,
}

impl Default for BenchmarkSettings {
    fn default() -> Self {
        Self {
            profile: BenchmarkProfile::Standard,
            cpu_workers: None,
            gpu_adapter_id: None,
            disk_mount_point: None,
            disk_allow_write: true,
            disk_write_limit: DiskWriteLimit::Standard,
            network_provider: NetworkProviderId::Cloudflare,
            network_data_profile: NetworkDataProfile::Standard,
            network_privacy_accepted: false,
            network_share_results: false,
            save_history: true,
            cooldown: true,
            sustained_secs: 60,
            show_raw_measurements: false,
            show_methodology: true,
            debug_logging: false,
        }
    }
}

impl BenchmarkSettings {
    pub fn validate(&self) -> crate::errors::AppResult<()> {
        let invalid = |m: &str| Err(AppError::InvalidArgument(m.to_owned()));
        if self
            .cpu_workers
            .is_some_and(|w| w == 0 || w > super::MAX_CPU_WORKERS)
        {
            return invalid("Invalid CPU worker count.");
        }
        if !(super::MIN_SUSTAINED_SECS..=super::MAX_SUSTAINED_SECS).contains(&self.sustained_secs) {
            return invalid("Invalid sustained test length.");
        }
        let long = |v: &Option<String>, max| v.as_ref().is_some_and(|s| s.len() > max);
        if long(&self.gpu_adapter_id, 128) || long(&self.disk_mount_point, 4_096) {
            return invalid("Invalid benchmark device selection.");
        }
        Ok(())
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub enum GpuDeviceType {
    Discrete,
    Integrated,
    Virtual,
    Software,
    Other,
}

/// A GPU adapter as seen through one graphics API. The same physical GPU
/// can appear once per backend (e.g. DirectX 12 and Vulkan).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(test, derive(ts_rs::TS), ts(export))]
#[serde(rename_all = "camelCase")]
pub struct GpuAdapterInfo {
    /// Stable id: `backend:vendor:device:ordinal`.
    pub id: String,
    pub name: String,
    pub vendor: String,
    /// PCI vendor/device ids in hex, when the backend reports them.
    pub vendor_id: String,
    pub device_id: String,
    pub backend: String,
    pub device_type: GpuDeviceType,
    pub driver: String,
    pub driver_info: String,
    pub timestamp_queries: bool,
    pub max_storage_buffer_mib: u32,
    /// The adapter the system reports as high-performance.
    pub preferred: bool,
}
